using System.Collections.Immutable;
using Aict.Beta;
using Aict.Core;
using Aict.Storage;
using Microsoft.VisualStudio.TestTools.UnitTesting;
namespace Aict.Core.Tests;
[TestClass] public sealed class BetaTests {
    sealed class Clock:IClock {
        public bool UserSessionPresent{get;set;}=true;public string BootId{get;set;}="boot-one";public long Uptime{get;set;}=100000;public long AwakeMilliseconds{get;set;}=100000;public DateTimeOffset UtcNow{get;set;}=new(2026,11,3,6,0,0,TimeSpan.Zero);
        public void Add(int milliseconds,bool sleep=false){Uptime+=milliseconds;UtcNow+=TimeSpan.FromMilliseconds(milliseconds);if(!sleep)AwakeMilliseconds+=milliseconds;}
    }
    static readonly ApplicationTarget App=new(ApplicationTarget.Prefix+new string('A',64),"示例应用","Example.exe",3072);
    static (Authority Authority,Clock Clock,string Database) Create(int? trialSeconds=null){var c=new Clock();string p=Path.Combine(Environment.GetEnvironmentVariable("AICT_TEST_ROOT")!,Guid.NewGuid().ToString("N"),"beta.sqlite");Directory.CreateDirectory(Path.GetDirectoryName(p)!);return(new(StateRepository.CreateNew(p,Authority.Initial(c)),c,[],trialEndsUtc:trialSeconds is {} seconds?c.UtcNow.AddSeconds(seconds):null),c,p);}
    static async Task<Status> Status(Authority a)=>(await a.Handle(new())).Status!;
    static async Task Register(Authority a){var r=await a.Handle(new(){Command=Command.RegisterApplication,EditToken=(await Status(a)).EditToken,Application=App});Assert.IsTrue(r.Ok,r.Message);}
    static async Task<Response> Submit(Authority a,PolicyConfiguration p)=>await a.Handle(new(){Command=Command.SubmitPolicy,EditToken=(await Status(a)).EditToken,Policy=p});
    static RuleGroup Web()=>new(){Id=Guid.NewGuid(),Name="自定义网站",WebsiteMode=TargetMode.BlockSelected,WebsiteDomains=["example.com"],AlwaysBlock=true};
    static async Task Agent(Authority a,string? browser=null)=>Assert.IsTrue((await a.Handle(new(){Command=Command.AgentPulse,Agent=new(App.Id,false,0,browser)},true)).Ok);
    [TestMethod] public async Task CustomWebsitesAndAllowlistProduceIndependentBlockPredicates(){var(a,c,p)=Create();using(a){var g=Web() with {WebsiteExceptions=["mail.example.com"]};var h=Web() with {Id=Guid.NewGuid(),WebsiteMode=TargetMode.AllowSelected,WebsiteDomains=["mail.example.com"]};Assert.IsTrue((await Submit(a,new(){ChangeDelay=TimeSpan.Zero,Groups=[g,h]})).Ok);var plan=(await a.Desired()).Web;Assert.IsFalse(plan.Groups.Any(x=>Plans.Denies(x,"mail.example.com")));Assert.IsTrue(plan.Groups.Any(x=>Plans.Denies(x,"other.example.com")));Assert.IsTrue(plan.Groups.Any(x=>Plans.Denies(x,"unrelated.org")));}}
    [TestMethod] public async Task ExtensionRemovalAndUnmanagedFocusedProfileCannotReuseBackgroundHealth(){var(a,c,p)=Create();using(a){await Agent(a,"Edge");Assert.IsTrue((await Submit(a,new(){ChangeDelay=TimeSpan.Zero,Groups=[Web()]})).Ok);var hash=(await a.Desired()).Web.Fingerprint;var sample=new BrowserSample("Edge",Guid.NewGuid().ToString("N"),hash,true,false,"example.com");Assert.IsTrue((await a.Handle(new(){Command=Command.BrowserPulse,Browser=sample},true)).Ok);Assert.IsTrue((await a.Desired()).BrowserHealthy["Edge"]);await a.Handle(new(){Command=Command.BrowserPulse,Browser=sample with {Focused=false}},true);Assert.IsFalse((await a.Desired()).BrowserHealthy["Edge"]);c.Add(4000);Assert.IsFalse((await a.Desired()).BrowserHealthy["Edge"]);}}
    [TestMethod] public async Task OrdinaryGuiCannotFabricateAgentOrBrowserAcknowledgements(){var(a,c,p)=Create();using(a){Assert.IsFalse((await a.Handle(new(){Command=Command.AgentPulse,Agent=new(App.Id,false,0)})).Ok);Assert.IsFalse((await a.Handle(new(){Command=Command.BrowserPulse,Browser=new("Edge",Guid.NewGuid().ToString("N"),"",true,false,"example.com")})).Ok);}}
    [TestMethod] public async Task AppAndWebsiteInSameGroupConsumeQuotaOnlyOnceAndSurviveRestart(){var(a,c,p)=Create();await Register(a);await Agent(a,"Edge");var g=Web() with {AlwaysBlock=false,ApplicationMode=TargetMode.BlockSelected,ApplicationIds=[App.Id],DailyQuota=TimeSpan.FromSeconds(2)};Assert.IsTrue((await Submit(a,new(){ChangeDelay=TimeSpan.Zero,Groups=[g]})).Ok);await a.Handle(new(){Command=Command.BrowserPulse,Browser=new("Edge",Guid.NewGuid().ToString("N"),(await a.Desired()).Web.Fingerprint,true,false,"example.com")},true);c.Add(1000);var s=await Status(a);Assert.AreEqual(TimeSpan.FromSeconds(1).Ticks,s.Usage.Single().UsedTicks);await Agent(a,"Edge");c.Add(1000);Assert.AreEqual(1,(await a.Desired()).Apps.Denied.Length);a.Dispose();using var recovered=new Authority(StateRepository.OpenExisting(p),c,[]);Assert.AreEqual(TimeSpan.FromSeconds(2).Ticks,(await Status(recovered)).Usage.Single().UsedTicks);}
    [TestMethod] public async Task MissingAwakeTelemetryIsCensoredAndCannotResetQuota(){var(a,c,p)=Create();using(a){await Register(a);await Agent(a);var g=new RuleGroup{Id=Guid.NewGuid(),Name="每日额度",ApplicationMode=TargetMode.BlockSelected,ApplicationIds=[App.Id],DailyQuota=TimeSpan.FromMinutes(30)};await Submit(a,new(){ChangeDelay=TimeSpan.Zero,Groups=[g]});c.Add(6000);var s=await Status(a);Assert.IsTrue(s.Usage.Single().HasGap);Assert.AreEqual(0L,s.Usage.Single().UsedTicks);await Agent(a);Assert.AreEqual(1,(await a.Desired()).Apps.Denied.Length);}}
    [TestMethod] public async Task SleepIsNotChargedOrConvertedIntoUnknownUsage(){var(a,c,p)=Create();using(a){await Register(a);await Agent(a);var g=new RuleGroup{Id=Guid.NewGuid(),Name="额度",ApplicationMode=TargetMode.BlockSelected,ApplicationIds=[App.Id],DailyQuota=TimeSpan.FromMinutes(5)};await Submit(a,new(){ChangeDelay=TimeSpan.Zero,Groups=[g]});c.Add(3600000,true);var s=await Status(a);Assert.AreEqual(0L,s.Usage.Single().UsedTicks);Assert.IsFalse(s.Usage.Single().HasGap);}}
    [TestMethod] public async Task UninstallUsesFrozenDelayAndAppliesEvenDuringActiveBlock(){var(a,c,p)=Create();using(a){await Register(a);var g=new RuleGroup{Id=Guid.NewGuid(),Name="倒计时",ApplicationMode=TargetMode.BlockSelected,ApplicationIds=[App.Id],BlockUntilUtc=c.UtcNow+TimeSpan.FromSeconds(60),LockWhileBlocking=true};await Submit(a,new(){ChangeDelay=TimeSpan.FromSeconds(10),Groups=[g]});var r=await a.Handle(new(){Command=Command.RequestUninstall,EditToken=(await Status(a)).EditToken});Assert.IsNotNull(r.Status!.Pending);Assert.AreEqual(ChangePurpose.Uninstall,r.Status.Pending.Purpose);c.Add(11000);Assert.IsTrue((await Status(a)).UninstallReady);}}
    [TestMethod] public async Task MultipleAppAllowlistsIntersectAndKeepExceptionsLocal(){var(a,c,p)=Create();using(a){await Register(a);var b=App with {Id=ApplicationTarget.Prefix+new string('B',64),FileName="Other.exe"};await a.Handle(new(){Command=Command.RegisterApplication,EditToken=(await Status(a)).EditToken,Application=b});var one=new RuleGroup{Id=Guid.NewGuid(),Name="允许一",ApplicationMode=TargetMode.AllowSelected,ApplicationIds=[App.Id],AlwaysBlock=true};var two=one with {Id=Guid.NewGuid(),Name="允许二",ApplicationIds=[b.Id]};await Submit(a,new(){ChangeDelay=TimeSpan.Zero,Groups=[one,two]});var plan=(await a.Desired()).Apps;Assert.AreEqual(2,plan.Whitelists.Length);Assert.IsTrue(plan.Whitelists.Any(g=>!g.Applications.Any(t=>t.Id==App.Id)));Assert.AreEqual(plan.Fingerprint,PolicyJson.Sha256(PolicyJson.Serialize(plan)));}}
    [TestMethod] public async Task WallRollbackDoesNotUnlockRulesAndNewBootDoesNotResetUsage(){var(a,c,p)=Create();await Register(a);await Submit(a,new(){ChangeDelay=TimeSpan.Zero,Groups=[new(){Id=Guid.NewGuid(),Name="锁定",ApplicationMode=TargetMode.BlockSelected,ApplicationIds=[App.Id],AlwaysBlock=true,LockWhileBlocking=true}]});c.Add(1000);c.UtcNow-=TimeSpan.FromMinutes(10);Assert.IsFalse((await Status(a)).ClockConsistent);Assert.IsFalse((await Submit(a,new(){Groups=[]})).Ok);a.Dispose();}
    [TestMethod] public async Task WaitingForUserLoginDoesNotExhaustQuota(){var(a,c,p)=Create();using(a){await Register(a);await Submit(a,new(){ChangeDelay=TimeSpan.Zero,Groups=[new(){Id=Guid.NewGuid(),Name="额度",ApplicationMode=TargetMode.BlockSelected,ApplicationIds=[App.Id],DailyQuota=TimeSpan.FromMinutes(5)}]});c.UserSessionPresent=false;c.Add(60000);var s=await Status(a);Assert.IsFalse(s.Usage.Single().HasGap);Assert.AreEqual(0L,s.Usage.Single().UsedTicks);}}
    [TestMethod] public void LegacyPolicyFingerprintDoesNotChangeWhenNewOptionalFieldsAreAbsent(){var old=new PolicyConfiguration{Groups=[Web()]};string json=PolicyJson.Serialize(old);Assert.IsFalse(json.Contains("blockUntilUtc"));Assert.AreEqual(json,PolicyJson.Serialize(PolicyJson.Parse<PolicyConfiguration>(json)));Assert.ThrowsExactly<System.Text.Json.JsonException>(()=>PolicyJson.Parse<Request>("{\"command\":\"Status\",\"clock\":{\"trusted\":true}}"));}
    [TestMethod] public async Task TighteningDuringLockedBlockIsImmediateAndCanRegisterNewTargets(){var(a,c,p)=Create();using(a){var g=Web() with {LockWhileBlocking=true};await Submit(a,new(){ChangeDelay=TimeSpan.FromMinutes(1),Groups=[g]});await Register(a);var r=await Submit(a,(await Status(a)).Policy with {Groups=[g with {WebsiteDomains=["example.com","other.org"]}]});Assert.IsNull(r.Status!.Pending);Assert.AreEqual(2,(await a.Desired()).Web.Groups.Single().Domains.Length);}}
    [TestMethod] public async Task RelaxationKeepsOldPlanUntilDeadlineAndSwitchesWhileOldRuleIsStillBlocking(){var(a,c,p)=Create();using(a){var g=Web() with {LockWhileBlocking=true};await Submit(a,new(){ChangeDelay=TimeSpan.FromSeconds(10),Groups=[g]});var r=await Submit(a,(await Status(a)).Policy with {Groups=[g with {WebsiteExceptions=["mail.example.com"]}]});Assert.IsNotNull(r.Status!.Pending);Assert.IsTrue((await a.Desired()).Web.Groups.Any(g=>Plans.Denies(g,"mail.example.com")));c.Add(9000);Assert.IsTrue((await a.Desired()).Web.Groups.Any(g=>Plans.Denies(g,"mail.example.com")));c.Add(1000);Assert.IsNull((await Status(a)).Pending);Assert.IsFalse((await a.Desired()).Web.Groups.Any(g=>Plans.Denies(g,"mail.example.com")));}}
    [TestMethod] public async Task ReplacingPendingPayloadRestartsWaitButIdenticalResubmitDoesNot(){var(a,c,p)=Create();using(a){var g=Web();await Submit(a,new(){ChangeDelay=TimeSpan.FromSeconds(30),Groups=[g]});var target=(await Status(a)).Policy with {Groups=[g with {WebsiteExceptions=["mail.example.com"]}]};var first=(await Submit(a,target)).Status!.Pending!;c.Add(5000);var same=(await Submit(a,target)).Status!.Pending!;Assert.AreEqual(first.Id,same.Id);var edited=(await Submit(a,target with {Groups=[g with {Enabled=false}]})).Status!.Pending!;Assert.AreNotEqual(first.Id,edited.Id);Assert.AreEqual(first.NotBeforeUtc.AddSeconds(5),edited.NotBeforeUtc);}}
    [TestMethod] public async Task PendingAutomaticSwitchSurvivesBackendRestart(){var(a,c,p)=Create();var g=Web() with {LockWhileBlocking=true};await Submit(a,new(){ChangeDelay=TimeSpan.FromSeconds(10),Groups=[g]});await Submit(a,(await Status(a)).Policy with {Groups=[g with {Enabled=false}]});a.Dispose();c.Add(11000);using var recovered=new Authority(StateRepository.OpenExisting(p),c,[]);Assert.IsNull((await Status(recovered)).Pending);Assert.IsFalse((await Status(recovered)).Policy.Groups.Single().Enabled);}
    [TestMethod] public async Task ImmediateTighteningCancelsOlderRelaxationWithoutWeakeningItsBase(){var(a,c,p)=Create();using(a){var g=Web();await Submit(a,new(){ChangeDelay=TimeSpan.FromMinutes(1),Groups=[g]});await Submit(a,(await Status(a)).Policy with {Groups=[g with {Enabled=false}]});var r=await Submit(a,(await Status(a)).Policy with {Groups=[g with {WebsiteDomains=["example.com","other.org"]}]});Assert.IsNull(r.Status!.Pending);c.Add(61000);Assert.IsTrue((await Status(a)).Policy.Groups.Single().Enabled);}}
    [TestMethod] public async Task RemovingLastWebsiteLeavesAppEnforcementButReleasesAllWebsiteLayers(){var(a,c,p)=Create();using(a){await Register(a);var g=Web() with {ApplicationMode=TargetMode.BlockSelected,ApplicationIds=[App.Id]};await Submit(a,new(){ChangeDelay=TimeSpan.FromSeconds(5),Groups=[g]});var r=await Submit(a,(await Status(a)).Policy with {Groups=[g with {WebsiteDomains=[],WebsiteExceptions=[]}]});Assert.IsNotNull(r.Status!.Pending);Assert.IsTrue((await a.Desired()).Web.Required);c.Add(5000);var desired=await a.Desired();Assert.IsFalse(desired.Web.Required);Assert.IsTrue(desired.Web.Groups.IsEmpty);Assert.AreEqual(1,desired.Apps.Denied.Length);}}
    [TestMethod] public async Task EmptyWebsiteAllowlistStillBlocksAllButEmptyBlacklistDoesNotRequireExtension(){var(a,c,p)=Create();using(a){await Register(a);var g=Web() with {WebsiteMode=TargetMode.AllowSelected,WebsiteDomains=[]};await Submit(a,new(){ChangeDelay=TimeSpan.Zero,Groups=[g]});Assert.IsTrue((await a.Desired()).Web.Required);Assert.IsTrue(Plans.Denies((await a.Desired()).Web.Groups.Single(),"example.org"));await Submit(a,(await Status(a)).Policy with {Groups=[g with {WebsiteMode=TargetMode.BlockSelected,ApplicationMode=TargetMode.BlockSelected,ApplicationIds=[App.Id]}]});Assert.IsFalse((await a.Desired()).Web.Required);}}
    [TestMethod] public async Task HostTrialExpiryPreservesAndDisablesRulesCancelsPendingAndRejectsReactivation(){var(a,c,p)=Create(10);using(a){var g=Web();await Submit(a,new(){ChangeDelay=TimeSpan.FromMinutes(1),Groups=[g]});await Submit(a,(await Status(a)).Policy with {Groups=[g with {Enabled=false}]});c.Add(10000);var s=await Status(a);Assert.IsTrue(s.TrialExpired);Assert.IsFalse(s.Policy.Groups.Single().Enabled);Assert.AreEqual(g.Name,s.Policy.Groups.Single().Name);Assert.IsNull(s.Pending);Assert.IsFalse((await a.Desired()).Web.Required);Assert.IsFalse((await Submit(a,s.Policy with {Groups=[g]})).Ok);var uninstall=await a.Handle(new(){Command=Command.RequestUninstall,EditToken=(await Status(a)).EditToken});Assert.IsTrue(uninstall.Status!.UninstallReady);}}
    [TestMethod] public async Task HostTrialRejectsAppAllowlistAndDoesNotLoseExpiryAcrossRestart(){var(a,c,p)=Create(10);var end=c.UtcNow.AddSeconds(10);await Register(a);var g=Web() with {ApplicationMode=TargetMode.AllowSelected,ApplicationIds=[App.Id]};Assert.IsFalse((await Submit(a,new(){ChangeDelay=TimeSpan.Zero,Groups=[g]})).Ok);await Submit(a,new(){ChangeDelay=TimeSpan.Zero,Groups=[Web()]});a.Dispose();c.Add(11000);using var recovered=new Authority(StateRepository.OpenExisting(p),c,[],trialEndsUtc:end);Assert.IsTrue((await Status(recovered)).TrialExpired);Assert.IsFalse((await Status(recovered)).Policy.Groups.Single().Enabled);}
    [TestMethod] public async Task FailedNetworkApplyIsNotReportedAsConfirmedRestriction(){var(a,c,p)=Create();using(a){await Submit(a,new(){ChangeDelay=TimeSpan.Zero,Groups=[Web()]});await a.Observe((await a.Desired()).Apps,null,null,false,"network error",networkConfirmed:false);Assert.IsFalse((await Status(a)).Websites.GateConfirmed);Assert.IsFalse((await Status(a)).Websites.FirewallClosed);}}
    [TestMethod] public async Task HostSafetyRequiresFreshConfirmedReleasedStateAndRunningService(){var(a,c,p)=Create(1);using(a){await Submit(a,new(){ChangeDelay=TimeSpan.Zero,Groups=[Web()]});c.Add(1000);var plan=await a.Desired();await a.Observe(plan.Apps,null,plan.Web.Fingerprint,false,null,networkConfirmed:true);var s=await Status(a);Assert.IsFalse(HostTrialSafety.NeedsIndependentCleanup(s,c.UtcNow,c.UtcNow,true));Assert.IsTrue(HostTrialSafety.NeedsIndependentCleanup(s,c.UtcNow,c.UtcNow.AddSeconds(-6),true));Assert.IsTrue(HostTrialSafety.NeedsIndependentCleanup(s,c.UtcNow,c.UtcNow,false));Assert.IsTrue(HostTrialSafety.NeedsIndependentCleanup(s with {Websites=s.Websites with {GateConfirmed=false}},c.UtcNow,c.UtcNow,true));Assert.IsTrue(HostTrialSafety.NeedsIndependentCleanup(s with {Websites=s.Websites with {FirewallClosed=true}},c.UtcNow,c.UtcNow,true));}}
    [TestMethod] public async Task ContinuousUsePassesThirtyMinutesAndRestartWithoutDisablingOrCancellingPending(){
        var(a,c,p)=Create();var g=Web() with {LockWhileBlocking=true};
        Assert.IsTrue((await Submit(a,new(){ChangeDelay=TimeSpan.FromHours(3),Groups=[g]})).Ok);
        await Submit(a,(await Status(a)).Policy with {Groups=[g with {WebsiteExceptions=["mail.example.com"]}]});
        var pending=(await Status(a)).Pending!;c.Add(31*60000);
        var s=await Status(a);Assert.IsNull(s.TrialEndsUtc);Assert.IsFalse(s.TrialExpired);Assert.IsTrue(s.Policy.Groups.Single().Enabled);Assert.AreEqual(pending.Id,s.Pending!.Id);Assert.AreEqual(TimeSpan.FromHours(3),s.Policy.ChangeDelay);Assert.IsTrue((await a.Desired()).Web.Required);a.Dispose();
        using var recovered=new Authority(StateRepository.OpenExisting(p),c,[]);var restored=await Status(recovered);Assert.IsTrue(restored.Policy.Groups.Single().Enabled);Assert.AreEqual(pending.Id,restored.Pending!.Id);Assert.AreEqual(pending.NotBeforeUtc,restored.Pending.NotBeforeUtc);
        Assert.IsTrue((await Submit(recovered,restored.Policy with {Groups=[g with {WebsiteDomains=["example.com","other.org"]}]})).Ok);
    }
    [TestMethod] public async Task ContinuousHostStillRejectsApplicationAllowlist(){
        var(a,c,p)=Create();await Register(a);a.Dispose();using var host=new Authority(StateRepository.OpenExisting(p),c,[],restrictApplicationAllowlist:true);
        Assert.IsFalse((await Submit(host,new(){ChangeDelay=TimeSpan.Zero,Groups=[Web() with {ApplicationMode=TargetMode.AllowSelected,ApplicationIds=[App.Id]}]})).Ok);
    }

}
